# What if I identify each rectangular region of solid color?
def find_rectangular_regions(grid):
    h, w = grid.shape
    visited = set()
    rectangles = []

    for r in range(h):
        for c in range(w):
            if (r, c) in visited:
                continue

            color = grid[r, c]

            # Check if this forms a rectangle
            # Expand in all directions
            top = r
            bottom = h
            left = c
            right = w

            while top > 0 and grid[top-1, c] == color:
                top -= 1
            while bottom < h and grid[bottom, c] == color:
                bottom += 1
            while left > 0 and grid[r, left-1] == color:
                left -= 1
            while right < w and grid[r, right] == color:
                right += 1

            # Verify rectangle
            is_rectangle = True
            for rr in range(top, bottom):
                for cc in range(left, right):
                    if grid[rr, cc] != color:
                        is_rectangle = False
                        break
                if not is_rectangle:
                    break

            if is_rectangle:
                rectangles.append((color, top, bottom, left, right))
                for rr in range(top, bottom):
                    for cc in range(left, right):
                        visited.add((rr, cc))

    return rectangles

